def joincmd(av,d,no,out):
 if len(av)<4:return 1
 c1,f1,c2,f2=av[:4]; a=read(f1,d); b=read(f2,d); h1=[] if no else a.pop(0); h2=[] if no else b.pop(0); i=parse_sel(c1,h1)[0]; j=parse_sel(c2,h2)[0]; m={r[j].strip().lower() if '--no-case' in av else r[j].strip():[] for r in b}
